// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.daoimport androidx.room.Daoimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.Queryimport com.roshan.persona.database.entity.ConversationStateEntityimport com.roshan.persona.database.entity.LlmCacheEntity@Daointerface LlmCacheDao {    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun insert(entity: LlmCacheEntity): Long    @Query("SELECT * FROM llm_cache WHERE prompt_hash = :hash AND expires_at > :now LIMIT 1")    suspend fun getByHash(hash: String, now: Long): LlmCacheEntity?    @Query("UPDATE llm_cache SET hit_count = hit_count + 1, last_accessed = :now WHERE id = :id")    suspend fun incrementHitCount(id: Long, now: Long)    @Query("DELETE FROM llm_cache WHERE expires_at < :now")    suspend fun deleteExpired(now: Long): Int    @Query("DELETE FROM llm_cache WHERE embedding_model_version != :version")    suspend fun deleteForModelVersionChange(version: String): Int    @Query("SELECT COUNT(*) FROM llm_cache")    suspend fun count(): Int}@Daointerface ConversationStateDao {    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun upsert(entity: ConversationStateEntity): Long    @Query("SELECT * FROM conversation_states WHERE session_id = :sessionId AND stage = 'NEEDS_INPUT' AND expires_at > :now LIMIT 1")    suspend fun getActiveForSession(sessionId: String, now: Long): ConversationStateEntity?    @Query("DELETE FROM conversation_states WHERE session_id = :sessionId")    suspend fun deleteForSession(sessionId: String)    @Query("DELETE FROM conversation_states WHERE expires_at < :now")    suspend fun deleteExpired(now: Long): Int    @Query("SELECT COUNT(*) FROM conversation_states")    suspend fun count(): Int    @Query("SELECT DISTINCT session_id FROM conversation_states")    suspend fun getAllSessions(): List<String>}